/* eslint-disable @typescript-eslint/no-unused-expressions */

import fromString = require( './index' );


// TESTS //

// The function returns an unsigned 64-bit integer...
{
	fromString( '1234' ); // $ExpectType Uint64
	fromString( '0xabcd' ); // $ExpectType Uint64
	fromString( '0b1010' ); // $ExpectType Uint64
	fromString( '0o1234' ); // $ExpectType Uint64
}

// The compiler throws an error if the function is provided an argument which is not a string...
{
	fromString( true ); // $ExpectError
	fromString( false ); // $ExpectError
	fromString( null ); // $ExpectError
	fromString( 123 ); // $ExpectError
	fromString( {} ); // $ExpectError
	fromString( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	fromString(); // $ExpectError
	fromString( '5', '3' ); // $ExpectError
}
